(5401988, 776304, 104966, '<td valign="top">This is great!</td>', 'This is great!', '2009-03-26 11:34:44.000000', NULL, 1),
(5402039, 776399, 99981, '<td valign="top">The idea and makeup are good, but i really don''t like the pink border and the reflection of the flash at her back. Besides the flash, her face stills a little dark. Maybe a different place would be better to take this shot, maybe a little makeup to the scenery would be great! Sorry if i was rude, good luck!</td>', 'The idea and makeup are good, but i really don''t like the pink border and the reflection of the flash at her back. Besides the flash, her face stills a little dark. Maybe a different place would be better to take this shot, maybe a little makeup to the scenery would be great! Sorry if i was rude, good luck!', '2009-03-26 12:41:19.000000', NULL, 1),
(5402040, 775070, 99981, '<td valign="top">Ok, the idea was good, but people who don''t read the title will give you a really low score, because it DNMC! I can''t give you a high score too, because the title is the last think i see when i''m voting! Hope you don''t take this bad, i like the shot, just not for this challenge! Good luck!</td>', 'Ok, the idea was good, but people who don''t read the title will give you a really low score, because it DNMC! I can''t give you a high score too, because the title is the last think i see when i''m voting! Hope you don''t take this bad, i like the shot, just not for this challenge! Good luck!', '2009-03-26 12:43:51.000000', NULL, 1),
