(5402060, 774879, 99981, '<td valign="top">Hahaha nice shot! One of my favorites so far.</td>', 'Hahaha nice shot! One of my favorites so far.', '2009-03-26 13:02:37.000000', NULL, 1),
(5402084, 775893, 98141, '<td valign="top">The lighting here really conveys the idea of a location/situation that your title solidifies. Mouths make language and debate is certainly a language of it''s own.</td>', 'The lighting here really conveys the idea of a location/situation that your title solidifies. Mouths make language and debate is certainly a language of it''s own.', '2009-03-26 13:18:17.000000', NULL, 1),
(5402087, 776329, 98141, '<td valign="top">The language of emotion? Facial expression and body language. Hair, makeup and background colors all look really cool and work together well.</td>', 'The language of emotion? Facial expression and body language. Hair, makeup and background colors all look really cool and work together well.', '2009-03-26 13:20:18.000000', NULL, 1),
(5402090, 776191, 98141, '<td valign="top">Written language, a wonderful form of expression. I wish that literacy were universal, though I suppose your title refers to the concept of love. Great lighting/colors in this.</td>', 'Written language, a wonderful form of expression. I wish that literacy were universal, though I suppose your title refers to the concept of love. Great lighting/colors in this.', '2009-03-26 13:21:10.000000', NULL, 1),
