(5403863, 775295, 43774, '<td valign="top">Very cute!!</td>', 'Very cute!!', '2009-03-27 12:08:03.000000', NULL, 1),
(5403935, 775060, 73884, '<td valign="top">Nice use of color and shapes but hardly relevant to the challenge itself. Yes, it is abstract but then any entry from the "Abstract Motion" challenge would qualify for this one. Not voting yet.</td>', 'Nice use of color and shapes but hardly relevant to the challenge itself. Yes, it is abstract but then any entry from the "Abstract Motion" challenge would qualify for this one. Not voting yet.', '2009-03-27 13:28:43.000000', NULL, 1),
