(5404509, 776247, 105164, '<td valign="top">overall I like this picture. the on thing that bothers me is the use of a child''s hand. Probably not old enough to read a book like this.</td>', 'overall I like this picture. the on thing that bothers me is the use of a child''s hand. Probably not old enough to read a book like this.', '2009-03-27 22:08:04.000000', NULL, 1),
(5404511, 775598, 105113, '<td valign="top">This is one of my favorites. I love the way that you caught the reflection.</td>', 'This is one of my favorites. I love the way that you caught the reflection.', '2009-03-27 22:11:18.000000', NULL, 1),
(5404513, 776204, 105113, '<td valign="top">One of my favorites!!! A great photograph showing an under-represented language.</td>', 'One of my favorites!!! A great photograph showing an under-represented language.', '2009-03-27 22:14:51.000000', NULL, 1),
(5404514, 776247, 105113, '<td valign="top">Love the lighting.</td>', 'Love the lighting.', '2009-03-27 22:16:12.000000', NULL, 1),
(5404515, 775598, 105164, '<td valign="top">I love this picture. It is easily one of my favorites and therefore got my highest rating within this competition. One small gripe. the picture to me says that the binary is flowing through the cable, and when unplugged, it drips a little out like a gas hose at the pump. But there is liquid on the outside of the plug. that''s it. thanks.</td>', 'I love this picture. It is easily one of my favorites and therefore got my highest rating within this competition. One small gripe. the picture to me says that the binary is flowing through the cable, and when unplugged, it drips a little out like a gas hose at the pump. But there is liquid on the outside of the plug. that''s it. thanks.', '2009-03-27 22:16:27.000000', NULL, 1),
(5404519, 776191, 105113, '<td valign="top">love the red background and lighting.</td>', 'love the red background and lighting.', '2009-03-27 22:23:17.000000', NULL, 1),
