(5404667, 776269, 102534, '<td valign="top">what a great shot and expression. That is one happy looking baby. well done</td>', 'what a great shot and expression. That is one happy looking baby. well done', '2009-03-27 23:46:56.000000', NULL, 1),
(5404670, 775284, 102534, '<td valign="top">poor little fella. speaks volumes</td>', 'poor little fella. speaks volumes', '2009-03-27 23:47:03.000000', NULL, 1),
(5404742, 776105, 93421, '<td valign="top">The ink on the hands and face are great!  Like the blue background on the left.  Would like the same (background) on the right though.  Wearing a Chinese collar would really have added something special to this shot.</td>', 'The ink on the hands and face are great!  Like the blue background on the left.  Would like the same (background) on the right though.  Wearing a Chinese collar would really have added something special to this shot.', '2009-03-28 02:22:41.000000', NULL, 1),
